using System; using System.Drawing; using System.Drawing.Imaging; using System.IO; using System.IO.Compression; using System.Runtime.InteropServices;
class Prep {
static void Main(){Directory.CreateDirectory("work/clean"); using(var z=ZipFile.Open("work/frames.zip",ZipArchiveMode.Create)) foreach(var f in Directory.GetFiles("work/frames","*.png")) {using(var original=new Bitmap(f)) using(var b=new Bitmap(original.Width,original.Height,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(b))g.DrawImageUnscaled(original,0,0); int w=b.Width,h=b.Height,n=w*h; var r=new Rectangle(0,0,w,h); var data=b.LockBits(r,ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb); byte[] p=new byte[n*4]; Marshal.Copy(data.Scan0,p,0,p.Length); bool[] mask=new bool[n]; int[] q=new int[n]; int head=0,tail=0; for(int i=0;i<n;i++){int x=i%w,y=i/w; if(x==0||y==0||x==w-1||y==h-1) {int k=i*4; if(Bg(p,k)){mask[i]=true;q[tail++]=i;}}} while(head<tail){int i=q[head++],x=i%w; int[] ns={x>0?i-1:-1,x<w-1?i+1:-1,i-w,i+w}; foreach(int j in ns)if(j>=0&&j<n&&!mask[j]&&Bg(p,j*4)){mask[j]=true;q[tail++]=j;}} for(int i=0;i<n;i++) {if(mask[i] || (i%w>550 && i/w<55)){p[i*4]=p[i*4+1]=p[i*4+2]=p[i*4+3]=0;}} Marshal.Copy(p,0,data.Scan0,p.Length);b.UnlockBits(data); var e=z.CreateEntry(Path.GetFileName(f),CompressionLevel.Fastest);using(var s=e.Open())b.Save(s,ImageFormat.Png);if(Path.GetFileName(f)=="0031.png"||Path.GetFileName(f)=="0600.png"||Path.GetFileName(f)=="0798.png")b.Save("work/clean/"+Path.GetFileName(f)); }} }
static bool Bg(byte[] p,int k){int b=p[k],g=p[k+1],r=p[k+2];return (g>90 && g-r>12 && b-r>6) || (r>220&&g>235&&b>220);}
}


